import ast
from pathlib import Path

def count_function_lines(func_node):
    return func_node.end_lineno - func_node.lineno + 1

files_to_check = [
    'mlebench/competitions/3d-object-detection-for-autonomous-vehicles/prepare.py',
    'mlebench/competitions/3d-object-detection-for-autonomous-vehicles/mAP_evaluation.py',
    'mlebench/competitions/inaturalist-2019-fgvc6/prepare.py',
    'mlebench/competitions/herbarium-2021-fgvc8/prepare.py',
    'mlebench/competitions/vinbigdata-chest-xray-abnormalities-detection/grade.py',
]

max_func = {'file': '', 'name': '', 'lines': 0}

for filepath in files_to_check:
    try:
        with open(filepath, 'r') as f:
            tree = ast.parse(f.read(), filename=filepath)
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                lines = count_function_lines(node)
                if lines > max_func['lines']:
                    max_func = {'file': filepath, 'name': node.name, 'lines': lines}
                    print(f'{filepath}: {node.name} = {lines} lines')
    except Exception as e:
        print(f'Error processing {filepath}: {e}')

print('\\nLongest function found:')
print(f\"File: {max_func['file']}\")
print(f\"Function: {max_func['name']}\")
print(f\"Lines: {max_func['lines']}\")
